const http = require('http');
const crypto = require('crypto');

// Secure message framing protocol implementation
// Supports chunked binary messages with integrity verification

const MAX_CHUNK_SIZE = 65536;
const MAX_TOTAL_SIZE = 10 * 1024 * 1024; // 10MB
const MAX_CHUNKS = 1024;
const HMAC_KEY = crypto.randomBytes(32);

class SecureFrameParser {
  constructor() {
    this.chunks = [];
    this.totalReceived = 0;
    this.expectedChunks = 0;
    this.headerParsed = false;
    this.complete = false;
  }

  // Parse frame header: [magic(4)] [version(2)] [numChunks(2)] [totalSize(4)] [hmac(32)]
  parseHeader(buffer) {
    if (buffer.length < 44) {
      return { error: 'Header too short' };
    }

    const magic = buffer.readUInt32BE(0);
    if (magic !== 0x53454346) { // 'SECF'
      return { error: 'Invalid magic bytes' };
    }

    const version = buffer.readUInt16BE(4);
    if (version !== 1) {
      return { error: 'Unsupported version' };
    }

    const numChunks = buffer.readUInt16BE(6);
    if (numChunks === 0 || numChunks > MAX_CHUNKS) {
      return { error: 'Invalid chunk count' };
    }

    const totalSize = buffer.readUInt32BE(8);
    if (totalSize === 0 || totalSize > MAX_TOTAL_SIZE) {
      return { error: 'Invalid total size' };
    }

    const providedHmac = buffer.slice(12, 44);
    const headerData = buffer.slice(0, 12);
    const expectedHmac = crypto.createHmac('sha256', HMAC_KEY)
      .update(headerData)
      .digest();

    if (!crypto.timingSafeEqual(providedHmac, expectedHmac)) {
      return { error: 'Header integrity check failed' };
    }

    this.expectedChunks = numChunks;
    this.expectedTotalSize = totalSize;
    this.headerParsed = true;

    return { success: true, remaining: buffer.slice(44) };
  }

  // Parse chunk: [chunkIndex(2)] [chunkLen(2)] [data(chunkLen)]
  parseChunk(buffer) {
    if (!this.headerParsed) {
      return { error: 'Header not yet parsed' };
    }

    if (buffer.length < 4) {
      return { error: 'Chunk header too short', needMore: true };
    }

    const chunkIndex = buffer.readUInt16BE(0);
    const chunkLen = buffer.readUInt16BE(2);

    if (chunkIndex >= this.expectedChunks) {
      return { error: 'Chunk index out of bounds' };
    }

    if (chunkLen > MAX_CHUNK_SIZE) {
      return { error: 'Chunk too large' };
    }

    if (buffer.length < 4 + chunkLen) {
      return { error: 'Incomplete chunk data', needMore: true };
    }

    const chunkData = buffer.slice(4, 4 + chunkLen);
    this.chunks[chunkIndex] = chunkData;
    this.totalReceived += chunkLen;

    if (this.totalReceived > MAX_TOTAL_SIZE) {
      return { error: 'Total size exceeded' };
    }

    return { success: true, consumed: 4 + chunkLen, remaining: buffer.slice(4 + chunkLen) };
  }

  // Reassemble all chunks into final buffer
  reassemble() {
    if (this.chunks.length !== this.expectedChunks) {
      return { error: 'Missing chunks' };
    }

    // Validate all chunks are present
    for (let i = 0; i < this.expectedChunks; i++) {
      if (!this.chunks[i]) {
        return { error: `Missing chunk ${i}` };
      }
    }

    // Calculate actual total size from chunks
    let actualTotal = 0;
    for (let i = 0; i < this.chunks.length; i++) {
      actualTotal += this.chunks[i].length;
    }

    // Security check: verify total matches expected
    if (actualTotal !== this.expectedTotalSize) {
      return { error: 'Size mismatch' };
    }

    // Allocate output buffer and copy chunks safely
    const output = Buffer.alloc(actualTotal);
    let offset = 0;

    for (let i = 0; i < this.chunks.length; i++) {
      this.chunks[i].copy(output, offset);
      offset += this.chunks[i].length;
    }

    return { success: true, data: output };
  }
}

// Process uploaded binary data with size-based routing
function processMessage(data) {
  // Apply transformation based on content type detection
  const header = data.slice(0, Math.min(16, data.length));

  if (isCompressedFormat(header)) {
    return decompressAndValidate(data);
  }

  return { processed: true, size: data.length, hash: crypto.createHash('sha256').update(data).digest('hex') };
}

function isCompressedFormat(header) {
  if (header.length < 2) return false;
  // Check for gzip magic
  return header[0] === 0x1f && header[1] === 0x8b;
}

function decompressAndValidate(data) {
  const zlib = require('zlib');
  try {
    const decompressed = zlib.gunzipSync(data, { maxOutputLength: MAX_TOTAL_SIZE });
    return { processed: true, size: decompressed.length, hash: crypto.createHash('sha256').update(decompressed).digest('hex') };
  } catch (e) {
    return { error: 'Decompression failed' };
  }
}

// Allocation pool for reusable buffers
class BufferPool {
  constructor(poolSize, bufferSize) {
    this.pool = [];
    this.bufferSize = bufferSize;
    // Pre-allocate pool
    for (let i = 0; i < poolSize; i++) {
      this.pool.push(Buffer.alloc(bufferSize));
    }
  }

  acquire() {
    if (this.pool.length > 0) {
      return this.pool.pop();
    }
    return Buffer.alloc(this.bufferSize);
  }

  release(buf) {
    if (buf.length === this.bufferSize && this.pool.length < 100) {
      buf.fill(0);
      this.pool.push(buf);
    }
  }
}

// Compute padded allocation size for alignment
// Returns size rounded up to next 64-byte boundary
function computeAlignedSize(headerSize, payloadSize) {
  // Safely combine sizes with overflow check
  const rawSize = headerSize + payloadSize;
  if (rawSize > MAX_TOTAL_SIZE || rawSize < 0) {
    throw new Error('Size overflow');
  }
  const aligned = (rawSize + 63) & ~63;
  return aligned;
}

// Build response frame with header and payload
function buildResponseFrame(payload, metadata) {
  const metaJson = JSON.stringify(metadata);
  const metaBuffer = Buffer.from(metaJson, 'utf8');

  // Header: [responseType(1)] [metaLen(2)] [payloadLen(4)] = 7 bytes
  const headerSize = 7;
  const payloadLen = payload.length;
  const metaLen = metaBuffer.length;

  // Validate sizes
  if (metaLen > 65535) {
    throw new Error('Metadata too large');
  }
  if (payloadLen > MAX_TOTAL_SIZE) {
    throw new Error('Payload too large');
  }

  // Calculate total frame size with safe addition
  const totalNeeded = headerSize + metaLen + payloadLen;
  if (totalNeeded > MAX_TOTAL_SIZE || totalNeeded < 0) {
    throw new Error('Frame too large');
  }
  const totalSize = computeAlignedSize(headerSize + metaLen, payloadLen);
  const frame = Buffer.alloc(totalSize);

  // Write header
  frame.writeUInt8(0x01, 0); // response type
  frame.writeUInt16BE(metaLen, 1);
  frame.writeUInt32BE(payloadLen, 3);

  // Write metadata
  metaBuffer.copy(frame, headerSize);

  // Write payload after metadata
  payload.copy(frame, headerSize + metaLen);

  return frame;
}

// Rate limiter using token bucket
class TokenBucket {
  constructor(capacity, refillRate) {
    this.capacity = capacity;
    this.tokens = capacity;
    this.refillRate = refillRate;
    this.lastRefill = Date.now();
  }

  consume() {
    this.refill();
    if (this.tokens > 0) {
      this.tokens--;
      return true;
    }
    return false;
  }

  refill() {
    const now = Date.now();
    const elapsed = (now - this.lastRefill) / 1000;
    this.tokens = Math.min(this.capacity, this.tokens + elapsed * this.refillRate);
    this.lastRefill = now;
  }
}

const rateLimiters = new Map();
const MAX_RATE_LIMITERS = 10000;
const RATE_LIMITER_IDLE_MS = 5 * 60 * 1000; // prune buckets idle > 5min
const bufferPool = new BufferPool(16, 4096);

// Prune stale rate limiter entries to bound memory usage (CWE-770 mitigation).
function pruneRateLimiters() {
  const now = Date.now();
  for (const [id, bucket] of rateLimiters) {
    if (now - bucket.lastRefill > RATE_LIMITER_IDLE_MS) {
      rateLimiters.delete(id);
    }
  }
}

function getRateLimiter(clientId) {
  if (!rateLimiters.has(clientId)) {
    // Enforce a hard cap on the number of tracked clients.
    if (rateLimiters.size >= MAX_RATE_LIMITERS) {
      pruneRateLimiters();
      if (rateLimiters.size >= MAX_RATE_LIMITERS) {
        // Evict the oldest inserted entry to make room.
        const oldestKey = rateLimiters.keys().next().value;
        if (oldestKey !== undefined) {
          rateLimiters.delete(oldestKey);
        }
      }
    }
    rateLimiters.set(clientId, new TokenBucket(10, 2));
  }
  return rateLimiters.get(clientId);
}

// Periodically prune idle entries.
const pruneTimer = setInterval(pruneRateLimiters, RATE_LIMITER_IDLE_MS);
if (pruneTimer.unref) pruneTimer.unref();

// Main server
const server = http.createServer((req, res) => {
  const clientIp = req.socket.remoteAddress;
  const limiter = getRateLimiter(clientIp);

  if (!limiter.consume()) {
    res.writeHead(429);
    res.end('Rate limited');
    return;
  }

  if (req.method === 'POST' && req.url === '/upload') {
    const contentLength = parseInt(req.headers['content-length'], 10);

    if (isNaN(contentLength) || contentLength <= 0 || contentLength > MAX_TOTAL_SIZE) {
      res.writeHead(400);
      res.end('Invalid content length');
      return;
    }

    const chunks = [];
    let received = 0;

    req.on('data', (chunk) => {
      received += chunk.length;
      if (received > contentLength) {
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });

    req.on('end', () => {
      try {
        const body = Buffer.concat(chunks);
        const parser = new SecureFrameParser();

        const headerResult = parser.parseHeader(body);
        if (headerResult.error) {
          res.writeHead(400);
          res.end(JSON.stringify({ error: headerResult.error }));
          return;
        }

        let remaining = headerResult.remaining;
        while (remaining.length > 0) {
          const chunkResult = parser.parseChunk(remaining);
          if (chunkResult.error) {
            if (chunkResult.needMore) break;
            res.writeHead(400);
            res.end(JSON.stringify({ error: chunkResult.error }));
            return;
          }
          remaining = chunkResult.remaining;
        }

        const assembled = parser.reassemble();
        if (assembled.error) {
          res.writeHead(400);
          res.end(JSON.stringify({ error: assembled.error }));
          return;
        }

        const result = processMessage(assembled.data);
        const responseFrame = buildResponseFrame(
          Buffer.from(JSON.stringify(result)),
          { timestamp: Date.now(), clientIp: clientIp }
        );

        res.writeHead(200, { 'Content-Type': 'application/octet-stream' });
        res.end(responseFrame);
      } catch (e) {
        res.writeHead(500);
        res.end('Internal error');
      }
    });
  } else {
    res.writeHead(404);
    res.end('Not found');
  }
});

